interface Money {
  kobo: number;
  currency: "NGN" | "USD";
}

function total(items: Money[]): Money {
  const currency = items[0]?.currency ?? "NGN";
  if (items.some((m) => m.currency !== currency)) throw new Error("mixed currencies");
  return { kobo: items.reduce((sum, m) => sum + m.kobo, 0), currency };
}

console.log(total([{ kobo: 100, currency: "NGN" }, { kobo: 250, currency: "NGN" }]));
try {
  total([{ kobo: 100, currency: "NGN" }, { kobo: 40, currency: "USD" }]);
} catch (error) {
  console.log((error as Error).message);
}

