type Currency = "NGN" | "USD" | "GBP";
type FxRate = [from: Currency, to: Currency, rate: number];

const rates: FxRate[] = [["USD", "NGN", 1550], ["GBP", "NGN", 2050]];

function convert(amount: number, from: Currency, to: Currency, table: FxRate[]): number {
  if (from === to) return amount;
  const found = table.find(([f, t]) => f === from && t === to);
  if (found === undefined) throw new Error(`no rate ${from}->${to}`);
  return Math.round(amount * found[2]);
}

console.log(convert(40, "USD", "NGN", rates));
